<?php
declare(strict_types=1);namespace Vendi\Integrations;use RuntimeException;
final class HttpClient{public function request(string$method,string$url,array$headers=[],?array$body=null):array{$ch=curl_init($url);$h=['Accept: application/json'];foreach($headers as$k=>$v)$h[]=$k.': '.$v;if($body!==null)$h[]='Content-Type: application/json';curl_setopt_array($ch,[CURLOPT_CUSTOMREQUEST=>$method,CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>30,CURLOPT_HTTPHEADER=>$h,CURLOPT_POSTFIELDS=>$body===null?null:json_encode($body,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)]);$raw=curl_exec($ch);$code=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);if($raw===false)throw new RuntimeException('Error de conexión: '.curl_error($ch));$data=json_decode($raw,true);if($code<200||$code>=300)throw new RuntimeException('Proveedor respondió '.$code.': '.substr($raw,0,500));return is_array($data)?$data:[];}}
